import json
from collections import deque
import sys

KEYS = ('Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony')
EDGE_KEYS = ('Depends', 'Before', 'After', 'Needs', 'Requires')


def solve(lines):
    sys.setrecursionlimit(100000)
    blocks = []
    cur = None
    for raw in lines:
        s = raw.strip()
        if not s or s.startswith('#'):
            continue
        if s.startswith('[') and s.endswith(']'):
            continue
        toks = s.split()
        if toks[0] == 'TARGET':
            if len(toks) != 2:
                return 'PARSE_ERROR'
            cur = {'kind': 'TARGET', 'name': toks[1], 'id': '', 'dirs': []}
            blocks.append(cur)
        elif toks[0] == 'OVERRIDE':
            if len(toks) != 3:
                return 'PARSE_ERROR'
            cur = {'kind': 'OVERRIDE', 'name': toks[1], 'id': toks[2], 'dirs': []}
            blocks.append(cur)
        else:
            if cur is None:
                return 'PARSE_ERROR'
            if s.count('=') != 1:
                return 'PARSE_ERROR'
            k, v = s.split('=')
            k = k.strip()
            v = v.strip()
            if k not in KEYS:
                return 'PARSE_ERROR'
            if k == 'Phony':
                if v not in ('yes', 'no'):
                    return 'PARSE_ERROR'
                cur['dirs'].append(('Phony', v))
            else:
                cur['dirs'].append((k, v.split()))

    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if ra < rb:
            parent[rb] = ra
        else:
            parent[ra] = rb

    all_names = set()
    for b in blocks:
        find(b['name'])
        all_names.add(b['name'])
        for k, vals in b['dirs']:
            if k == 'Alias':
                for x in vals:
                    union(b['name'], x)
                    all_names.add(x)
    for b in blocks:
        for k, vals in b['dirs']:
            if k in EDGE_KEYS:
                for x in vals:
                    all_names.add(x)

    proc = [b for b in blocks if b['kind'] == 'TARGET'] + \
        sorted([b for b in blocks if b['kind'] == 'OVERRIDE'], key=lambda b: b['id'])

    nodes = []
    seen = set()

    def add(n):
        if n not in seen:
            seen.add(n)
            nodes.append(n)

    acc = {}
    torder = []
    for b in proc:
        U = find(b['name'])
        add(U)
        if U not in acc:
            acc[U] = {k: [] for k in EDGE_KEYS}
            torder.append(U)
        for k, vals in b['dirs']:
            if k in EDGE_KEYS:
                for x in vals:
                    c = find(x)
                    if c not in acc[U][k]:
                        acc[U][k].append(c)

    adj = {}

    def edge(a, b2):
        add(a)
        add(b2)
        lst = adj.setdefault(a, [])
        if b2 not in lst:
            lst.append(b2)

    for U in torder:
        for x in acc[U]['Depends']:
            edge(x, U)
        for y in acc[U]['Before']:
            edge(U, y)
        for z in acc[U]['After']:
            edge(z, U)
        for w in acc[U]['Needs']:
            edge(U, w)
        for v in acc[U]['Requires']:
            edge(U, v)

    for n in sorted(set(find(x) for x in all_names)):
        add(n)

    index = {}
    low = {}
    onstack = set()
    st = []
    sccs = []
    counter = [0]

    def strong(v):
        index[v] = counter[0]
        low[v] = counter[0]
        counter[0] += 1
        st.append(v)
        onstack.add(v)
        for w in adj.get(v, []):
            if w not in index:
                strong(w)
                low[v] = min(low[v], low[w])
            elif w in onstack:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = []
            while True:
                w = st.pop()
                onstack.discard(w)
                comp.append(w)
                if w == v:
                    break
            sccs.append(comp)

    for v in nodes:
        if v not in index:
            strong(v)

    comp_of = {}
    for i, c in enumerate(sccs):
        for v in c:
            comp_of[v] = i

    nidx = {n: i for i, n in enumerate(nodes)}
    cycles = []
    for c in sccs:
        if len(c) >= 2 or (c[0] in adj.get(c[0], [])):
            cycles.append(sorted(c))
    cycles.sort()

    m = len(sccs)
    first = [min(nidx[v] for v in c) for c in sccs]
    cadj = [[] for _ in range(m)]
    cindeg = [0] * m
    cseen = set()
    for v in nodes:
        for w in adj.get(v, []):
            a = comp_of[v]
            bb = comp_of[w]
            if a != bb and (a, bb) not in cseen:
                cseen.add((a, bb))
                cadj[a].append(bb)
                cindeg[bb] += 1

    init = sorted([i for i in range(m) if cindeg[i] == 0], key=lambda i: first[i])
    q = deque(init)
    order = []
    while q:
        i = q.popleft()
        order.extend(sorted(sccs[i]))
        for j in cadj[i]:
            cindeg[j] -= 1
            if cindeg[j] == 0:
                q.append(j)

    return json.dumps({'order': order, 'cycles': cycles}, separators=(',', ':'))
